import { spawn } from "node:child_process";
import { once } from "node:events";
import { existsSync } from "node:fs";
import { createRequire } from "node:module";
import { createConnection } from "node:net";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { Duplex } from "node:stream";
import { fileURLToPath } from "node:url";
import { ISOLATED_PROXY_ENDPOINT } from "./browser-connection.js";
import { failure } from "./failures.js";
const ISOLATE_HELPER = "/usr/local/libexec/sand-playwright-isolate";
const EXEC_DAEMON_NODE = "/exec-daemon/node";
const ISOLATED_WORKER_REQUIREMENTS = [
    ISOLATE_HELPER,
    "/usr/bin/bwrap",
    "/usr/bin/socat",
    "/usr/bin/sudo",
    "/usr/bin/unshare",
];
export function resolveDefaultWorkerLauncherKind(options = {}) {
    if (options.dogfood ?? process.env.SAND_PLAYWRIGHT_ALLOW_DOGFOOD === "1") {
        return "unisolated";
    }
    const platform = options.platform ?? process.platform;
    const pathExists = options.pathExists ?? existsSync;
    return platform === "linux" && ISOLATED_WORKER_REQUIREMENTS.every(pathExists)
        ? "isolated"
        : "unisolated";
}
export function createDefaultLauncher(kind = resolveDefaultWorkerLauncherKind()) {
    return {
        launch: kind === "isolated" ? launchIsolatedWorker : launchUnisolatedWorker,
    };
}
export function resolveUnisolatedWorkerNode(options = {}) {
    const platform = options.platform ?? process.platform;
    const pathExists = options.pathExists ?? existsSync;
    return platform === "linux" && pathExists(EXEC_DAEMON_NODE)
        ? EXEC_DAEMON_NODE
        : (options.fallback ?? process.execPath);
}
async function launchUnisolatedWorker(proxyEndpoint) {
    let home;
    try {
        process.stderr.write("sand-playwright-mcp unsafe_worker_isolation=unisolated\n");
        home = await mkdtemp(path.join(tmpdir(), "sand-pw-worker-"));
        const workerHome = home;
        const workerPath = fileURLToPath(new URL("./worker.js", import.meta.url));
        const packageRoot = path.dirname(path.dirname(workerPath));
        const dependencyReadArgs = existsSync(new URL("./worker.cjs", import.meta.url))
            ? []
            : unbundledWorkerDependencyReadArgs();
        const nodeArgs = [
            "--max-old-space-size=384",
            "--permission",
            `--allow-fs-read=${packageRoot}`,
            ...dependencyReadArgs,
            "--allow-fs-read=/proc/sys/fs/binfmt_misc/WSLInterop",
            "--allow-fs-read=/run/WSL",
            workerPath,
        ];
        const command = resourceControlCommand(resolveUnisolatedWorkerNode(), nodeArgs);
        const child = spawn(command.executable, command.arguments, {
            detached: true,
            env: {
                HOME: workerHome,
                TMPDIR: workerHome,
                LANG: "C.UTF-8",
                NODE_ENV: "production",
                SAND_PLAYWRIGHT_PROXY_ENDPOINT: proxyEndpoint,
            },
            stdio: ["ignore", "pipe", "pipe", "pipe"],
        });
        const pid = child.pid;
        const channel = child.stdio[3];
        if (pid === undefined ||
            child.stdout === null ||
            child.stderr === null ||
            !(channel instanceof Duplex)) {
            child.kill("SIGKILL");
            await rm(workerHome, { recursive: true, force: true });
            return {
                kind: "rejected",
                failure: failure("launch_failed", "Worker IPC setup failed"),
            };
        }
        const exited = new Promise((resolve) => {
            child.once("exit", (code, signal) => {
                void rm(workerHome, { recursive: true, force: true });
                resolve({ code, signal });
            });
        });
        child.once("error", () => {
            killProcessGroup(pid, child.kill.bind(child), "SIGKILL");
        });
        return {
            kind: "admitted",
            value: {
                pid,
                proxyEndpoint,
                channel,
                stdout: child.stdout,
                stderr: child.stderr,
                exited,
                killProcessGroup(signal) {
                    killProcessGroup(pid, child.kill.bind(child), signal);
                },
            },
        };
    }
    catch {
        if (home !== undefined) {
            await rm(home, { recursive: true, force: true });
        }
        return {
            kind: "rejected",
            failure: failure("launch_failed", "Unisolated worker failed to launch"),
        };
    }
}
function unbundledWorkerDependencyReadArgs() {
    const require = createRequire(import.meta.url);
    return ["playwright-core", "zod"].map((dependency) => `--allow-fs-read=${path.dirname(require.resolve(`${dependency}/package.json`))}`);
}
async function launchIsolatedWorker(proxyEndpoint) {
    if (resolveDefaultWorkerLauncherKind({ dogfood: false }) !== "isolated") {
        return {
            kind: "rejected",
            failure: failure("runtime_unavailable", "The isolated browser worker is not installed"),
        };
    }
    let socket;
    try {
        const endpoint = new URL(proxyEndpoint);
        if (endpoint.protocol !== "ws:" ||
            (endpoint.hostname !== "127.0.0.1" && endpoint.hostname !== "::1") ||
            endpoint.port.length === 0) {
            return {
                kind: "rejected",
                failure: failure("invalid_input", "Worker proxy endpoint was rejected"),
            };
        }
        socket = createConnection({
            host: endpoint.hostname,
            port: Number(endpoint.port),
        });
        await once(socket, "connect");
        const child = spawn("/usr/bin/sudo", ["-n", "-C", "5", ISOLATE_HELPER], {
            detached: true,
            env: {
                LANG: "C.UTF-8",
                PATH: "/usr/sbin:/usr/bin:/sbin:/bin",
            },
            stdio: ["ignore", "pipe", "pipe", "pipe", socket],
        });
        socket.destroy();
        socket = undefined;
        return launchedWorker(child, ISOLATED_PROXY_ENDPOINT);
    }
    catch {
        socket?.destroy();
        return {
            kind: "rejected",
            failure: failure("launch_failed", "Isolated worker failed to launch"),
        };
    }
}
function launchedWorker(child, proxyEndpoint) {
    const pid = child.pid;
    const channel = child.stdio[3];
    if (pid === undefined ||
        child.stdout === null ||
        child.stderr === null ||
        !(channel instanceof Duplex)) {
        child.kill("SIGKILL");
        return {
            kind: "rejected",
            failure: failure("launch_failed", "Worker IPC setup failed"),
        };
    }
    const exited = new Promise((resolve) => {
        child.once("exit", (code, signal) => resolve({ code, signal }));
    });
    child.once("error", () => {
        killProcessGroup(pid, child.kill.bind(child), "SIGKILL");
    });
    return {
        kind: "admitted",
        value: {
            pid,
            proxyEndpoint,
            channel,
            stdout: child.stdout,
            stderr: child.stderr,
            exited,
            killProcessGroup(signal) {
                killProcessGroup(pid, child.kill.bind(child), signal);
            },
        },
    };
}
function resourceControlCommand(nodeExecutable, nodeArgs) {
    if (process.platform !== "linux" || !existsSync("/usr/bin/prlimit")) {
        return { executable: nodeExecutable, arguments: nodeArgs };
    }
    return {
        executable: "/usr/bin/prlimit",
        arguments: ["--nofile=256", "--", nodeExecutable, ...nodeArgs],
    };
}
function killProcessGroup(pid, fallback, signal) {
    try {
        process.kill(-pid, signal);
    }
    catch {
        fallback(signal);
    }
}
export function closedWorkerFailure() {
    return failure("worker_failed", "Worker exited without a valid result");
}
